import{_ as e,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"AI辅助开发的任务、上下文与验收","description":"任务契约、上下文、权限、技能、MCP接入、恢复与人工验收。","frontmatter":{"title":"AI辅助开发的任务、上下文与验收","description":"任务契约、上下文、权限、技能、MCP接入、恢复与人工验收。","showdocs":{"topics":[{"id":"ai","title":"AI 与 Codex","link":"/topics/ai/"},{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"}],"kind":"AI与Codex上手与对象","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"AI与Codex：任务契约、上下文与证据","summary":"任务契约、上下文、权限、技能、MCP接入、恢复与人工验收。","status":"active","related":[{"title":"全局 AGENTS.md","link":"/tools/ai/guide/global-agents","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"AI与Codex：完整实践与解答","link":"/tools/ai/practice/application","kind":"AI与Codex完整实践与解答","scope":"general","audience":"general"},{"title":"编辑器与IDE：完整实践与解答","link":"/tools/developer-tools/engineering/practice/application","kind":"编辑器与IDE完整实践与解答","scope":"general","audience":"general"},{"title":"Jira Software 使用技巧与 JQL 搜索指南","link":"/tools/developer-tools/engineering/guide/jira-software","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"},{"title":"Jira Software 使用技巧与 JQL 搜索指南 · 1. Jira 能解决什么问题至5. JQL 语句结构","link":"/tools/developer-tools/engineering/guide/jira-software-part-01","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"}],"prev":false,"next":{"text":"AI与Codex：完整实践与解答","link":"/tools/ai/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"AI与Codex：完整实践与解答","link":"/tools/ai/practice/application"}},"headers":[],"relativePath":"tools/ai/assisted-development-workflow.md","filePath":"tools/ai/assisted-development-workflow.md"}'),l={name:"tools/ai/assisted-development-workflow.md"};function o(p,a,n,d,h,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="ai辅助开发的任务、上下文与验收" tabindex="-1">AI辅助开发的任务、上下文与验收 <a class="header-anchor" href="#ai辅助开发的任务、上下文与验收" aria-label="Permalink to &quot;AI辅助开发的任务、上下文与验收&quot;">​</a></h1><h2 id="part-1" tabindex="-1">定义任务与必要上下文 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;定义任务与必要上下文 {#part-1}&quot;">​</a></h2><p>需能阅读 Python 函数和 JSON 用例。本页从任务范围、上下文选择讲到验收；<a href="/tools/ai/practice/application#source">离线任务包</a>用 <code>format_label</code> 的空白输入修复贯穿规则、候选补丁和审查表，不需要模型账号或 SDK。 示例未在本轮执行。</p><h3 id="part-1-contract" tabindex="-1">Codex 任务契约 <a class="header-anchor" href="#part-1-contract" aria-label="Permalink to &quot;Codex 任务契约 {#part-1-contract}&quot;">​</a></h3><p>Codex任务契约写明目标、允许修改的目录和验收依据。本课程只讨论离线文件，不调用模型；明确范围能帮助人工判断输出是否解决原问题，不能保证一次生成正确。</p><h3 id="part-1-context" tabindex="-1">Codex 上下文选择 <a class="header-anchor" href="#part-1-context" aria-label="Permalink to &quot;Codex 上下文选择 {#part-1-context}&quot;">​</a></h3><p>Codex上下文应覆盖相关接口、调用方与边界测试，按问题定位再读取。把历史材料与当前约束区分，摘录必要内容时保留出处，避免把压缩摘要当作代码事实。</p><h3 id="part-1-agents" tabindex="-1">Codex AGENTS.md <a class="header-anchor" href="#part-1-agents" aria-label="Permalink to &quot;Codex AGENTS.md {#part-1-agents}&quot;">​</a></h3><p>Codex的AGENTS.md用于稳定项目规则。官方说明存在用户级与目录层次指令；课程示例给出仓库规则文件，但具体发现机制、覆盖顺序和大小限制应依当前官方页及本次客户端环境核对。</p><p><span id="part-3-sources"></span></p><p><span id="part-2-sources"></span></p><h3 id="part-1-sources" tabindex="-1">依据与适用范围 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;依据与适用范围 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://developers.openai.com/codex/guides/agents-md" target="_blank" rel="noopener noreferrer">本课官方依据</a>，资料核对日2026-10-17。</li></ul><p>以上依据用于解释本文列明的规则；示例未执行，不代表产品全部能力或跨平台验证。历史资料的版本、账号与界面位置需按目标环境确认。</p><ul><li><a href="https://learn.chatgpt.com/docs/agent-approvals-security" target="_blank" rel="noopener noreferrer">OpenAI Docs：执行环境与安全</a></li><li><a href="https://developers.openai.com/codex/skills" target="_blank" rel="noopener noreferrer">OpenAI Docs：技能</a></li></ul><p>本地能力核对：本会话工具清单确实提供本地文件与终端工具，权限由会话沙箱和用户约束控制；这不是所有Codex客户端都具备相同工具的保证。未调用模型、SDK或API。</p><h2 id="part-2" tabindex="-1">控制权限、技能与验证证据 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;控制权限、技能与验证证据 {#part-2}&quot;">​</a></h2><h3 id="part-2-permissions" tabindex="-1">Codex 权限边界 <a class="header-anchor" href="#part-2-permissions" aria-label="Permalink to &quot;Codex 权限边界 {#part-2-permissions}&quot;">​</a></h3><p>Codex权限边界由执行环境控制。写作任务明确禁止运行示例或外发时，生成命令文本不等于获准执行；审批与沙箱是执行约束，不能因提示词要求就假定拥有系统权限。</p><h3 id="part-2-skills" tabindex="-1">Codex 技能文件 <a class="header-anchor" href="#part-2-skills" aria-label="Permalink to &quot;Codex 技能文件 {#part-2-skills}&quot;">​</a></h3><p>Codex技能以SKILL.md表达重复工作流。描述应限定触发条件与输入，正文说明步骤和验收；安装了技能不代表外部账号已连接，引用的脚本仍需审阅权限和副作用。</p><h3 id="part-2-evidence" tabindex="-1">Codex 验证证据 <a class="header-anchor" href="#part-2-evidence" aria-label="Permalink to &quot;Codex 验证证据 {#part-2-evidence}&quot;">​</a></h3><p>Codex验证证据应记录实际命令、退出状态和适用范围。仅源码审阅就写源码审阅；静态编译不代表服务运行。模型名称、费率和账号额度会变化，本课不复制旧价格或承诺可用模型。</p><h2 id="part-3" tabindex="-1">识别错误假设与范围漂移 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;识别错误假设与范围漂移 {#part-3}&quot;">​</a></h2><h3 id="part-3-hallucination" tabindex="-1">Codex 幻觉接口 <a class="header-anchor" href="#part-3-hallucination" aria-label="Permalink to &quot;Codex 幻觉接口 {#part-3-hallucination}&quot;">​</a></h3><p>Codex幻觉接口常表现为不存在的方法、错误版本参数或伪造引用。先查锁定依赖和官方定义，再做纯语法或类型核对；能编译仍不足以确认业务语义，必须对照需求逐项审阅。</p><h3 id="part-3-drift" tabindex="-1">Codex 范围漂移 <a class="header-anchor" href="#part-3-drift" aria-label="Permalink to &quot;Codex 范围漂移 {#part-3-drift}&quot;">​</a></h3><p>Codex范围漂移是改动扩展到任务之外。把每个变更映射到验收条件，无法对应的整理先移出补丁；长期任务用文件保存决策、当前状态与下一步，避免用重复读取全部仓库维持进度。</p><h3 id="part-3-cost" tabindex="-1">Codex 成本判断 <a class="header-anchor" href="#part-3-cost" aria-label="Permalink to &quot;Codex 成本判断 {#part-3-cost}&quot;">​</a></h3><p>Codex成本判断先区分订阅额度、API计量与实际任务记录。旧文的模型分工和价格仅代表历史上下文；本课只建议减少无关上下文、重复输出和返工，不以字符数直接推算所有模型的Token账单。</p><h2 id="part-4" tabindex="-1">AI 辅助开发实践 <a class="header-anchor" href="#part-4" aria-label="Permalink to &quot;AI 辅助开发实践 {#part-4}&quot;">​</a></h2><p><span id="part-4-_2-适用场景"></span><span id="part-4-_2-1-效果较好的场景"></span><span id="part-4-_2-2-效果有限的场景"></span><span id="part-4-_3-实际收益"></span><span id="part-4-_3-1-降低重复劳动"></span><span id="part-4-_3-2-提前发现遗漏"></span><span id="part-4-_3-3-加快方案探索"></span><span id="part-4-_3-4-提升基础代码质量"></span><span id="part-4-_4-主要问题与风险"></span><span id="part-4-_4-1-历史上下文理解不足"></span><span id="part-4-_4-2-上下文与-token-限制"></span><span id="part-4-_4-3-需求质量直接影响结果"></span><span id="part-4-_4-4-生成结果可能看似正确"></span><span id="part-4-_4-5-人工验收成本仍然存在"></span><span id="part-4-_5-推荐使用流程"></span></p><p>本文整理需求分析、编码、测试与审查中适合使用 AI 的任务，以及开发者需要提供和验收的内容。</p><h3 id="part-4-适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#part-4-适用场景" aria-label="Permalink to &quot;适用场景 {#part-4-适用场景}&quot;">​</a></h3><h4 id="part-4-效果较好的场景" tabindex="-1">效果较好的场景 <a class="header-anchor" href="#part-4-效果较好的场景" aria-label="Permalink to &quot;效果较好的场景 {#part-4-效果较好的场景}&quot;">​</a></h4><h5 id="part-4-需求分析" tabindex="-1">需求分析 <a class="header-anchor" href="#part-4-需求分析" aria-label="Permalink to &quot;需求分析 {#part-4-需求分析}&quot;">​</a></h5><p>在开发前拆解需求，补充正常流程、异常流程、边界条件和潜在风险，形成待确认问题清单。</p><h5 id="part-4-新功能与新服务开发" tabindex="-1">新功能与新服务开发 <a class="header-anchor" href="#part-4-新功能与新服务开发" aria-label="Permalink to &quot;新功能与新服务开发 {#part-4-新功能与新服务开发}&quot;">​</a></h5><p>对于上下文清晰、历史依赖较少的项目，AI 可以快速完成：</p><ul><li>项目或模块基础结构搭建</li><li>Handler、Service、Repository 等分层代码</li><li>数据结构、接口和错误处理框架</li><li>重复性较高的增删改查代码</li></ul><h5 id="part-4-独立逻辑与算法" tabindex="-1">独立逻辑与算法 <a class="header-anchor" href="#part-4-独立逻辑与算法" aria-label="Permalink to &quot;独立逻辑与算法 {#part-4-独立逻辑与算法}&quot;">​</a></h5><p>对于输入输出明确、依赖较少的逻辑，AI 通常能够较快产出可验证的实现，例如：</p><ul><li>牌型与规则计算</li><li>排序、过滤和数据统计</li><li>数据格式转换</li><li>独立工具函数</li></ul><h5 id="part-4-测试" tabindex="-1">测试 <a class="header-anchor" href="#part-4-测试" aria-label="Permalink to &quot;测试 {#part-4-测试}&quot;">​</a></h5><p>AI 可以根据实现补充：</p><ul><li>单元测试与表驱动测试</li><li>正常、异常和边界测试场景</li><li>Mock 数据与测试桩</li><li>未覆盖分支和回归风险提示</li></ul><h5 id="part-4-code-review" tabindex="-1">Code Review <a class="header-anchor" href="#part-4-code-review" aria-label="Permalink to &quot;Code Review {#part-4-code-review}&quot;">​</a></h5><p>AI 适合辅助发现常见问题，包括：</p><ul><li>明显的逻辑错误和遗漏分支</li><li>空指针、越界和错误未处理</li><li>并发安全与资源释放问题</li><li>简单的性能和代码规范问题</li></ul><h4 id="part-4-效果有限的场景" tabindex="-1">效果有限的场景 <a class="header-anchor" href="#part-4-效果有限的场景" aria-label="Permalink to &quot;效果有限的场景 {#part-4-效果有限的场景}&quot;">​</a></h4><p>以下场景不宜直接依赖 AI 完成：</p><ul><li>维护时间长、代码量大、业务约定复杂的历史项目</li><li>涉及资金、账号、权限、数据一致性等高风险逻辑</li><li>缺少需求文档，只能依赖口头约定或隐性知识的需求</li><li>修改范围跨越多个服务，但缺少完整调用链和协议说明的任务</li><li>线上紧急问题中未经验证的自动修改</li></ul><h3 id="part-4-实际收益" tabindex="-1">实际收益 <a class="header-anchor" href="#part-4-实际收益" aria-label="Permalink to &quot;实际收益 {#part-4-实际收益}&quot;">​</a></h3><h4 id="part-4-降低重复劳动" tabindex="-1">降低重复劳动 <a class="header-anchor" href="#part-4-降低重复劳动" aria-label="Permalink to &quot;降低重复劳动 {#part-4-降低重复劳动}&quot;">​</a></h4><p>AI 对模板化代码、数据结构转换、测试用例和文档整理的处理效率较高，可以减少重复编码时间。</p><h4 id="part-4-提前发现遗漏" tabindex="-1">提前发现遗漏 <a class="header-anchor" href="#part-4-提前发现遗漏" aria-label="Permalink to &quot;提前发现遗漏 {#part-4-提前发现遗漏}&quot;">​</a></h4><p>在需求评审和编码前引入 AI，可以从输入校验、异常处理、并发、兼容性和可测试性等角度补充检查项。</p><h4 id="part-4-加快方案探索" tabindex="-1">加快方案探索 <a class="header-anchor" href="#part-4-加快方案探索" aria-label="Permalink to &quot;加快方案探索 {#part-4-加快方案探索}&quot;">​</a></h4><p>开发人员可以让 AI 提供多个实现思路并比较复杂度、可维护性和风险，再结合项目实际情况选择方案。</p><h4 id="part-4-提升基础代码质量" tabindex="-1">提升基础代码质量 <a class="header-anchor" href="#part-4-提升基础代码质量" aria-label="Permalink to &quot;提升基础代码质量 {#part-4-提升基础代码质量}&quot;">​</a></h4><p>当项目规范和上下文明确时，AI 能够较稳定地遵循分层、命名、错误处理和测试要求，减少基础规范问题。</p><h3 id="part-4-主要问题与风险" tabindex="-1">主要问题与风险 <a class="header-anchor" href="#part-4-主要问题与风险" aria-label="Permalink to &quot;主要问题与风险 {#part-4-主要问题与风险}&quot;">​</a></h3><h4 id="part-4-历史上下文理解不足" tabindex="-1">历史上下文理解不足 <a class="header-anchor" href="#part-4-历史上下文理解不足" aria-label="Permalink to &quot;历史上下文理解不足 {#part-4-历史上下文理解不足}&quot;">​</a></h4><p>长期维护的项目通常包含大量隐性规则、兼容逻辑和跨服务依赖。AI 无法仅通过局部代码准确理解全部背景，容易出现：</p><ul><li>业务含义理解偏差</li><li>修改范围过大或过小</li><li>忽略历史数据和旧版本兼容</li><li>只修复表面问题，破坏原有调用链</li></ul><p>因此，历史项目应先提供模块说明、调用链、关键约束和相关代码范围，再让 AI 分阶段处理。</p><h4 id="part-4-上下文与-token-限制" tabindex="-1">上下文与 Token 限制 <a class="header-anchor" href="#part-4-上下文与-token-限制" aria-label="Permalink to &quot;上下文与 Token 限制 {#part-4-上下文与-token-限制}&quot;">​</a></h4><p>大型需求会持续消耗上下文。上下文过长或多次切换任务后，可能出现信息遗漏、回答不连续和实现质量下降。</p><p>建议将大任务拆分为“分析、方案、实现、测试、审查”等阶段，每个阶段明确输入、输出和完成标准，并将关键结论沉淀到文档中。</p><h4 id="part-4-需求质量直接影响结果" tabindex="-1">需求质量直接影响结果 <a class="header-anchor" href="#part-4-需求质量直接影响结果" aria-label="Permalink to &quot;需求质量直接影响结果 {#part-4-需求质量直接影响结果}&quot;">​</a></h4><p>“和上次一样”“按原逻辑处理”等描述依赖团队成员的长期记忆，AI 无法准确识别对应的历史方案和隐藏规则。</p><p>提交给 AI 的任务至少应包含：</p><ul><li>业务目标和非目标</li><li>输入、输出和接口约定</li><li>正常流程、异常流程和边界条件</li><li>涉及的模块、数据表和上下游服务</li><li>历史兼容要求</li><li>验收标准</li></ul><h4 id="part-4-生成结果可能看似正确" tabindex="-1">生成结果可能看似正确 <a class="header-anchor" href="#part-4-生成结果可能看似正确" aria-label="Permalink to &quot;生成结果可能看似正确 {#part-4-生成结果可能看似正确}&quot;">​</a></h4><p>AI 生成的代码通常结构完整，但仍可能存在错误假设、伪造接口、遗漏错误处理或测试只覆盖实现而未验证需求等问题。代码能够编译不代表业务正确。</p><h4 id="part-4-人工验收成本仍然存在" tabindex="-1">人工验收成本仍然存在 <a class="header-anchor" href="#part-4-人工验收成本仍然存在" aria-label="Permalink to &quot;人工验收成本仍然存在 {#part-4-人工验收成本仍然存在}&quot;">​</a></h4><p>AI 输出必须由开发人员负责验证，包括：</p><ul><li>确认需求理解和设计方案</li><li>检查代码修改范围</li><li>运行单元测试、集成测试和回归测试</li><li>核对兼容性、性能、安全与数据影响</li><li>完成人工 Code Review</li></ul><h3 id="part-4-推荐使用流程" tabindex="-1">推荐使用流程 <a class="header-anchor" href="#part-4-推荐使用流程" aria-label="Permalink to &quot;推荐使用流程 {#part-4-推荐使用流程}&quot;">​</a></h3><h4 id="part-4-第一步-准备上下文" tabindex="-1">第一步：准备上下文 <a class="header-anchor" href="#part-4-第一步-准备上下文" aria-label="Permalink to &quot;第一步：准备上下文 {#part-4-第一步-准备上下文}&quot;">​</a></h4><p>提供需求文档、相关代码范围、项目规范、调用链和历史兼容要求，避免一次性加载无关文件。</p><h4 id="part-4-第二步-先分析再修改" tabindex="-1">第二步：先分析再修改 <a class="header-anchor" href="#part-4-第二步-先分析再修改" aria-label="Permalink to &quot;第二步：先分析再修改 {#part-4-第二步-先分析再修改}&quot;">​</a></h4><p>先让 AI 输出需求理解、影响范围、风险点和实施计划。开发人员确认方向后，再进入编码阶段。</p><h4 id="part-4-第三步-拆分任务" tabindex="-1">第三步：拆分任务 <a class="header-anchor" href="#part-4-第三步-拆分任务" aria-label="Permalink to &quot;第三步：拆分任务 {#part-4-第三步-拆分任务}&quot;">​</a></h4><p>将复杂需求拆成可独立验证的小任务，每个任务明确：</p><ul><li>要修改什么</li><li>不允许修改什么</li><li>需要遵循哪些约束</li><li>如何验证完成</li></ul><h4 id="part-4-第四步-实现并自检" tabindex="-1">第四步：实现并自检 <a class="header-anchor" href="#part-4-第四步-实现并自检" aria-label="Permalink to &quot;第四步：实现并自检 {#part-4-第四步-实现并自检}&quot;">​</a></h4><p>要求 AI 在修改后执行格式化、静态检查和相关测试，并说明实际修改内容、验证结果和未覆盖风险。</p><h4 id="part-4-第五步-人工验收" tabindex="-1">第五步：人工验收 <a class="header-anchor" href="#part-4-第五步-人工验收" aria-label="Permalink to &quot;第五步：人工验收 {#part-4-第五步-人工验收}&quot;">​</a></h4><p>开发人员重点检查业务正确性、兼容逻辑、数据安全、并发行为和修改边界，不能只依据 AI 的自检结论。</p><h4 id="part-4-第六步-沉淀经验" tabindex="-1">第六步：沉淀经验 <a class="header-anchor" href="#part-4-第六步-沉淀经验" aria-label="Permalink to &quot;第六步：沉淀经验 {#part-4-第六步-沉淀经验}&quot;">​</a></h4><p>将反复出现的项目结构、编码规范、业务约束和验证命令写入项目文档，减少后续重复补充上下文的成本。</p><h3 id="part-4-公司实践" tabindex="-1">适用范围 <a class="header-anchor" href="#part-4-公司实践" aria-label="Permalink to &quot;适用范围 {#part-4-公司实践}&quot;">​</a></h3><h2 id="part-5" tabindex="-1">MCP 接入步骤 <a class="header-anchor" href="#part-5" aria-label="Permalink to &quot;MCP 接入步骤 {#part-5}&quot;">​</a></h2><h3 id="part-5-添加-mcp-服务器" tabindex="-1">添加 MCP 服务器 <a class="header-anchor" href="#part-5-添加-mcp-服务器" aria-label="Permalink to &quot;添加 MCP 服务器 {#part-5-添加-mcp-服务器}&quot;">​</a></h3><ol><li>进入 Codex 设置中的 MCP 服务器页面，选择添加服务器。</li><li>按目标服务提供的信息填写服务名称、协议类型、服务 URL 和所需鉴权信息。</li><li>保存配置，确认服务器已启用。</li></ol><h3 id="part-5-公司实践" tabindex="-1">适用范围 <a class="header-anchor" href="#part-5-公司实践" aria-label="Permalink to &quot;适用范围 {#part-5-公司实践}&quot;">​</a></h3><p>使用文档检索或诊断工具前，应确认目标环境、权限和数据范围；本页不提供内部服务配置。</p>',98)])])}const b=e(l,[["render",o]]);export{u as __pageData,b as default};
